(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.018 + t * 0.25) * 18 + Math.cos(y * 0.013 - t * 0.18) * 12;
  const w1y = Math.cos(y * 0.018 - t * 0.22) * 18 + Math.sin(x * 0.015 + t * 0.3) * 12;
  const w2x = Math.sin((x+w1y) * 0.025 + t * 0.15) * 8;
  const w2y = Math.cos((y+w1x) * 0.025 - t * 0.2) * 8;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
