    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.38+6)*60, 200+Math.sin(t*0.72)*55, 0.085, 1.8, 1.0],
    [200+Math.sin(t*0.55+2.5)*90, 220+Math.cos(t*0.48)*65, 0.075, 2.4, 0.9],
    [300+Math.cos(t*0.42+4.5)*75, 30+Math.sin(t*0.58+2)*45, 0.095, 2.0, 1.1]
  ];
  let aS = 0, iS = 0, wS = 0;
  for (const [sX, sY, f, sp, am] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const fade = am / (1 + d * 0.003);
    aS += Math.sin(d*f - t*sp) * fade;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * fade;
    wS += Math.sin(d*f*0.4 - t*sp*0.3 + 3.0) * fade * 0.5;
  }
  const act = aS/10, inh = iS/10, wave = wS/10;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.065+t*1.3)*Math.sin(sy*0.055-t*0.9)*0.3;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
