  const sp2 = Math.sin(dist*0.08+ang*2-t*2.0)*Math.cos(dist*0.03-ang*5+t*0.8)*0.2;
  const sp3 = Math.sin(dist*0.02-ang*6+t*0.5)*0.15;
  const spiral = sp1 + sp2 + sp3;
  const micro = (Math.sin(sx*0.22+t*3)*Math.sin(sy*0.22-t*2.7) + Math.sin((sx+sy)*0.18+t*1.8)*0.5)*0.2;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.25 + spiral)*2.2);
  const rd2 = Math.tanh((wave*1.5 + act*0.3 - inh*0.5 + micro)*1.8);
  const coupling = Math.tanh((rd1 + rd2*0.6 + spiral*0.4)*1.6);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const blend = coupling*0.7 + cell*0.15 + micro*0.15;
  const v = blend*0.5+0.5;
  const hueShift = Math.sin(t*0.15)*0.15;
  const pal = [
    [5,12,52],[10,45,95],[12,85,120],[18,135,135],
    [45,170,130],[140,195,85],[210,195,55],[230,155,55],
    [215,100,65],[180,55,70],[120,30,65],[60,18,55],[5,12,52]
  ];
  const shifted = v + hueShift;
